import 'dart:convert';
import 'dart:typed_data';

import '../../abi/smart_contract/query/return_code.dart';
import '../../utils/helpers.dart';
import '../address.dart';
import 'transaction_logs.dart';

/// Cross-shard / asynchronous execution output generated by the VM.
///
/// Every non-trivial transaction on MultiversX can produce one or more
/// `SmartContractResult` entries: refunds, cross-shard move-balance results,
/// asynchronous contract callbacks, and more. The `data` field follows the
/// `@<returnCode>@<returnData1>@<returnData2>...` hex-encoded layout, which is
/// decoded eagerly into [returnCode] / [returnData] by [fromJson].
///
/// Call types map to MultiversX's VM execution:
/// - `0` — direct SC call / refund
/// - `1` — async call initiated from another contract
/// - `2` — async callback landing back in the caller
///
/// #### Example
/// ```dart
/// final tx = await provider.getTransaction(hash, withProcessStatus: true);
/// for (final scr in tx.smartContractResults ?? <SmartContractResult>[]) {
///   if (scr.returnCode.isError) {
///     print('SCR failed: ${scr.errorMessage ?? scr.returnCode.message}');
///   } else {
///     for (final part in scr.returnData) {
///       print('Return part: 0x${_hex(part)}');
///     }
///   }
/// }
/// ```
class SmartContractResult {
  /// Creates a [SmartContractResult].
  const SmartContractResult({
    required this.hash,
    required this.nonce,
    required this.value,
    required this.sender,
    required this.receiver,
    required this.data,
    required this.returnCode,
    required this.returnData,
    this.previousHash,
    this.originalHash,
    this.gasLimit,
    this.gasPrice,
    this.callType = 0,
    this.errorMessage,
    this.logs,
    this.raw = const <String, dynamic>{},
  });

  /// Parses a smart-contract result from an API / Gateway payload.
  ///
  /// `data` is expected to be a `@`-delimited hex string (with or without the
  /// leading `@`). The first segment is the return code, the rest are return
  /// values. If the payload is not in this shape it is preserved byte-for-byte
  /// in the result's [data] field and [returnData] is left empty.
  factory SmartContractResult.fromJson(Map<String, dynamic> json) {
    final String hash =
        optionalAs<String>(json['hash'], 'hash') ??
        optionalAs<String>(json['txHash'], 'txHash') ??
        '';
    final int nonce = optionalInt(json['nonce'], 'nonce') ?? 0;
    final dynamic valueRaw = json['value'];
    final String value = valueRaw is String
        ? valueRaw
        : (valueRaw is num ? valueRaw.toString() : '0');
    final String senderStr = optionalAs<String>(json['sender'], 'sender') ?? '';
    final String receiverStr =
        optionalAs<String>(json['receiver'], 'receiver') ?? '';
    final String dataStr = optionalAs<String>(json['data'], 'data') ?? '';

    final _DecodedScrPayload decoded = _decodePayload(dataStr);

    final dynamic logsRaw = json['logs'];
    final TransactionLogs? logs = logsRaw is Map<String, dynamic>
        ? TransactionLogs.fromHttpResponse(logsRaw)
        : null;

    return SmartContractResult(
      hash: hash,
      nonce: nonce,
      value: value,
      sender: senderStr.isEmpty
          ? Address.empty()
          : Address.fromBech32(senderStr),
      receiver: receiverStr.isEmpty
          ? Address.empty()
          : Address.fromBech32(receiverStr),
      data: decoded.rawBytes,
      returnCode: decoded.returnCode,
      returnData: decoded.returnData,
      previousHash: optionalAs<String>(json['prevTxHash'], 'prevTxHash'),
      originalHash: optionalAs<String>(json['originalTxHash'], 'originalTxHash'),
      gasLimit: optionalInt(json['gasLimit'], 'gasLimit'),
      gasPrice: optionalInt(json['gasPrice'], 'gasPrice'),
      callType: optionalInt(json['callType'], 'callType') ?? 0,
      errorMessage: optionalAs<String>(json['returnMessage'], 'returnMessage'),
      logs: logs,
      raw: json,
    );
  }

  /// Result hash.
  final String hash;

  /// Nonce used for this result.
  final int nonce;

  /// EGLD value moved (as string of atomic units).
  final String value;

  /// Result sender.
  final Address sender;

  /// Result receiver.
  final Address receiver;

  /// Raw data bytes (whatever the `data` field decoded to — empty if missing).
  final Uint8List data;

  /// Decoded return code (first `@`-segment of data).
  final ReturnCode returnCode;

  /// Decoded return-data parts (subsequent `@`-segments, hex-decoded).
  final List<Uint8List> returnData;

  /// Hash of the previous transaction in the chain.
  final String? previousHash;

  /// Hash of the original transaction that triggered the call graph.
  final String? originalHash;

  /// Gas allowance for this SCR (if present).
  final int? gasLimit;

  /// Gas price for this SCR (if present).
  final int? gasPrice;

  /// VM call type (0 = direct, 1 = async, 2 = async callback).
  final int callType;

  /// Network-provided error message, if any.
  final String? errorMessage;

  /// Logs emitted by this result, if present.
  final TransactionLogs? logs;

  /// Raw JSON payload for access to provider-specific fields.
  final Map<String, dynamic> raw;

  /// Whether this result represents a successful execution.
  bool get isSuccess => returnCode.isSuccess;

  /// Whether this result represents a failed execution.
  bool get isFailure => returnCode.isError;

  /// Whether this result is an async call (callType `1`).
  bool get isAsyncCall => callType == 1;

  /// Whether this result is an async callback (callType `2`).
  bool get isAsyncCallback => callType == 2;

  @override
  String toString() =>
      'SmartContractResult(hash: $hash, returnCode: $returnCode, '
      'returnData: ${returnData.length} parts)';
}

class _DecodedScrPayload {
  const _DecodedScrPayload({
    required this.rawBytes,
    required this.returnCode,
    required this.returnData,
  });

  final Uint8List rawBytes;
  final ReturnCode returnCode;
  final List<Uint8List> returnData;
}

_DecodedScrPayload _decodePayload(String data) {
  if (data.isEmpty) {
    return _DecodedScrPayload(
      rawBytes: Uint8List(0),
      returnCode: ReturnCode.none,
      returnData: const <Uint8List>[],
    );
  }

  // The SCR data may arrive base64-encoded (API) or as raw UTF-8 (Gateway).
  // Try base64 first; fall back to treating the string as raw UTF-8.
  Uint8List rawBytes;
  String text = data;
  try {
    final Uint8List decoded = base64Decode(data);
    rawBytes = decoded;
    text = utf8.decode(decoded, allowMalformed: true);
  } catch (_) {
    rawBytes = Uint8List.fromList(utf8.encode(data));
  }

  final String trimmed = text.startsWith('@') ? text.substring(1) : text;
  if (!text.contains('@')) {
    return _DecodedScrPayload(
      rawBytes: rawBytes,
      returnCode: ReturnCode.none,
      returnData: const <Uint8List>[],
    );
  }

  final List<String> parts = trimmed.split('@');
  if (parts.isEmpty) {
    return _DecodedScrPayload(
      rawBytes: rawBytes,
      returnCode: ReturnCode.none,
      returnData: const <Uint8List>[],
    );
  }

  final ReturnCode code = _decodeReturnCode(parts.first);
  final List<Uint8List> returnParts = <Uint8List>[];
  for (int i = 1; i < parts.length; i++) {
    returnParts.add(_hexToBytes(parts[i]));
  }

  return _DecodedScrPayload(
    rawBytes: rawBytes,
    returnCode: code,
    returnData: returnParts,
  );
}

ReturnCode _decodeReturnCode(String segment) {
  if (segment.isEmpty) return ReturnCode.none;
  // Most protocol codes arrive as the ASCII string "ok" / "user error" / ...
  // Some are hex-encoded ("6f6b" = "ok"). Try hex first; fall back to raw.
  if (_looksLikeHex(segment)) {
    try {
      final Uint8List bytes = _hexToBytes(segment);
      final String asAscii = utf8.decode(bytes, allowMalformed: true);
      if (asAscii.isNotEmpty && _isPrintable(asAscii)) {
        return ReturnCode.parse(asAscii);
      }
    } catch (_) {
      // fall through
    }
  }
  return ReturnCode.parse(segment);
}

bool _looksLikeHex(String s) {
  if (s.isEmpty || s.length.isOdd) return false;
  for (int i = 0; i < s.length; i++) {
    final int code = s.codeUnitAt(i);
    final bool isHex =
        (code >= 0x30 && code <= 0x39) ||
        (code >= 0x61 && code <= 0x66) ||
        (code >= 0x41 && code <= 0x46);
    if (!isHex) return false;
  }
  return true;
}

bool _isPrintable(String s) {
  for (int i = 0; i < s.length; i++) {
    final int c = s.codeUnitAt(i);
    if (c < 0x20 || c > 0x7e) return false;
  }
  return true;
}

Uint8List _hexToBytes(String hex) {
  if (hex.isEmpty) return Uint8List(0);
  final String padded = hex.length.isOdd ? '0$hex' : hex;
  final Uint8List out = Uint8List(padded.length ~/ 2);
  for (int i = 0; i < out.length; i++) {
    out[i] = int.parse(padded.substring(i * 2, i * 2 + 2), radix: 16);
  }
  return out;
}

